pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C(0, new address[](0), new address[](0));
    }

    function testFuzz_property(bytes4 interfaceId) public {
        bool supports = c.supportsInterface(interfaceId);
        bool supportsIERC165 = c.supportsInterface(type(IERC165).interfaceId);
        bool supportsIAccessControl = c.supportsInterface(type(IAccessControl).interfaceId);

        // In the reference C, supportsInterface(interfaceId) returns true if and only if
        // interfaceId is type(IAccessControl).interfaceId or type(IERC165).interfaceId (or both).
        // Additionally, type(IERC165).interfaceId and type(IAccessControl).interfaceId themselves must return true.
        // The mutant always returns false, so it will violate this for at least one of these interface IDs.
        bool expected = (interfaceId == type(IAccessControl).interfaceId || interfaceId == type(IERC165).interfaceId);
        assertTrue(supports == expected && supportsIERC165 && supportsIAccessControl);
    }
}

