pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, new address[](0), new address[](0)); }
    function testFuzz_property(bytes4 interfaceId) public {
        bool result = c.supportsInterface(interfaceId);
        assertTrue(result || !result); // This assertion always passes for reference; for mutant, the property that must hold is: supportsInterface does not return false for an interfaceId it is supposed to support. However, the above DOES NOT distinguish.
        // We need a general rule: The contract must not return false for an interfaceId that it claims to support via its type constants.
        // So we assert: if interfaceId equals the known supported interface, it must return true.
        // But the property must be INVARIANT for ALL inputs for reference, and BROKEN for SOME input for mutant.
        // The reference rule: "supportsInterface does not return false for an interfaceId that is one of the supported interfaces (IERC165, IAccessControl)." This is not a GENERAL rule over ALL inputs; it only applies to specific interfaceIds.
        // We need a rule over ALL bytes4 inputs that holds for reference but fails for mutant.
        // The reference always returns a boolean; the mutant always returns false. The difference is that for SOME interfaceIds (the supported ones), the reference returns true while mutant returns false. For other interfaceIds, both return false.
        // So the property "supportsInterface returns true for at least one interfaceId" is true for reference (because the supported ones exist) but false for mutant. But that is not a rule over ALL inputs, it's an existential statement.
        // The universal rule over the function behavior: "supportsInterface does not return false for interfaceId = type(IERC165).interfaceId". That's not universal.
        // Another universal rule: "The result of supportsInterface is consistent: if interfaceId == type(IERC165).interfaceId then result is true, else if interfaceId == type(IAccessControl).interfaceId then result is true, else result is false." That holds for reference (due to the overridden supportsInterface logic) but for mutant, the first two conditions fail (returns false instead of true). That IS a universal rule that can be checked for all bytes4.
        // So we can assert: If interfaceId == type(IERC165).interfaceId or interfaceId == type(IAccessControl).interfaceId, then result == true; else result == false? No, reference doesn't guarantee false for non-matching, because super.supportsInterface might match other things? Actually, the reference's supportsInterface is: interfaceId == type(IAccessControl).interfaceId || super.supportsInterface(interfaceId); where super is ERC165, which returns true ONLY for type(IERC165).interfaceId. So reference returns true exactly for those two, false otherwise. So the rule "result == (interfaceId == type(IAccessControl).interfaceId || interfaceId == type(IERC165).interfaceId)" holds for all bytes4. For mutant, it fails for interfaceIds that are either of those two.
        // Hence we can assert that.
        bool expected = (interfaceId == type(IAccessControl).interfaceId || interfaceId == type(IERC165).interfaceId);
        bool result = c.supportsInterface(interfaceId);
        assertTrue(result == expected);
    }
}

