pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, new address[](0), new address[](0)); }

    function testFuzz_property(bytes32 role, address account, address admin) public {
        // admin must be different from address(0) and have admin role over 'role'
        vm.assume(admin != address(0));
        vm.assume(account != address(0));
        vm.assume(role != bytes32(0));

        // First, admin must be the admin of the role.
        // By default, admin of a role not set is DEFAULT_ADMIN_ROLE (bytes32(0)).
        // We make admin the admin for 'role' by calling _setRoleAdmin via the public getRoleAdmin?
        // Actually, only way to set admin externally is if msg.sender is current admin.
        // Since we deployed with empty proposers/executors, the deployer (this contract) has TIMELOCK_ADMIN_ROLE.
        // We'll give admin the TIMELOCK_ADMIN_ROLE, then from admin, set role admin to itself, then grant role to account.

        vm.prank(address(this));
        c.grantRole(c.TIMELOCK_ADMIN_ROLE(), admin);

        vm.startPrank(admin);
        // admin can now set role admin because it has TIMELOCK_ADMIN_ROLE, and TIMELOCK_ADMIN_ROLE is its own admin.
        // Wait, _setRoleAdmin requires being the current admin of the role. By default, a new role has admin DEFAULT_ADMIN_ROLE (bytes32(0)),
        // which is administered by TIMELOCK_ADMIN_ROLE? No, DEFAULT_ADMIN_ROLE is its own admin. Let's simplify:
        // grant admin the DEFAULT_ADMIN_ROLE, then from admin, set role's admin to admin, then grant role to account.
        vm.stopPrank();

        // Deployer has DEFAULT_ADMIN_ROLE.
        vm.prank(address(this));
        c.grantRole(c.DEFAULT_ADMIN_ROLE(), admin);

        vm.startPrank(admin);
        // admin is now admin of DEFAULT_ADMIN_ROLE? Actually DEFAULT_ADMIN_ROLE is admin of itself.
        // So admin can't change DEFAULT_ADMIN_ROLE's admin. But we don't need that.
        // We can just grant role directly? No, to grant role we need to be the admin of that role.
        // By default, role has admin bytes32(0) (DEFAULT_ADMIN_ROLE). So an account with DEFAULT_ADMIN_ROLE can grant role.
        // admin has DEFAULT_ADMIN_ROLE, so it can grant 'role' to 'account'.
        c.grantRole(role, account);
        vm.stopPrank();

        // Reference: hasRole returns true. Mutant: returns false.
        bool hasIt = c.hasRole(role, account);
        assertTrue(hasIt);
    }
}

