pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C(0, new address[](0), new address[](0));
    }

    function testFuzz_property(address proposer) public {
        // The reference holds: if proposer is given PROPOSER_ROLE and tries to schedule an operation
        // (which internally calls hasRole), it succeeds. The mutant always returns false from hasRole,
        // so the onlyRole check inside schedule reverts.
        bytes32 proposerRole = c.PROPOSER_ROLE();
        bytes32 adminRole = c.TIMELOCK_ADMIN_ROLE();

        // Grant proposer role to the fuzzed address
        vm.prank(address(this));
        c.grantRole(proposerRole, proposer);

        // Schedule a simple operation as the proposer
        vm.prank(proposer);
        bytes32 salt = bytes32(uint256(1));
        uint256 delay = c.getMinDelay();
        try c.schedule(address(0), 0, "", bytes32(0), salt, delay) {
            // Reference succeeds, mutant reverts
            assertTrue(true);
        } catch {
            // Mutant reverts due to hasRole returning false
            assertTrue(false);
        }
    }
}

