import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C(0, address(this), address(this));
    }

    function testFuzz_property(address caller, address target, bytes32 role) public {
        vm.assume(caller != address(0));
        vm.assume(target != address(0));
        vm.assume(caller != target);
        vm.assume(role != bytes32(0));

        // Ensure caller has the role initially
        vm.prank(address(this));
        c.grantRole(role, caller);
        require(c.hasRole(role, caller), "setup failed: caller lacks role");

        // Record caller's membership before the operation
        bool hadRoleBefore = c.hasRole(role, caller);

        // Perform renounceRole as the caller, targeting a different account
        vm.prank(caller);
        try c.renounceRole(role, target) {
            // no revert
        } catch {
            // revert is fine
        }

        // After the operation, regardless of target or success, the caller's own membership must not have changed
        bool hasRoleAfter = c.hasRole(role, caller);
        assertTrue(hasRoleAfter == hadRoleBefore);
    }
}
